css:
.pe-sim-container {
    padding: 20px;
    background: linear-gradient(135deg, #f0f4f8 0%, #e2e8f0 100%);
    min-height: 100vh;
    font-family: -apple-system, BlinkMacSystemFont, 'Segoe UI', sans-serif;
}
.pe-sim-container .pe-sim-header {
    background: linear-gradient(135deg, #1a365d 0%, #2d3748 100%);
    color: white;
    padding: 30px;
    border-radius: 16px;
    margin-bottom: 24px;
    text-align: center;
    box-shadow: 0 8px 24px rgba(0,0,0,0.2);
}
.pe-sim-container .pe-sim-header h1 { margin: 0 0 8px 0; font-size: 1.8rem; }
.pe-sim-container .pe-sim-header p { margin: 0; opacity: 0.85; font-size: 1rem; }
.pe-sim-container .pe-sim-period-counter {
    text-align: center; font-size: 1.1rem; color: #4a5568;
    margin-bottom: 20px; font-weight: 600;
}
.pe-sim-container .pe-sim-fund-kpis {
    display: grid;
    grid-template-columns: repeat(auto-fit, minmax(140px, 1fr));
    gap: 12px; margin-bottom: 24px;
}
.pe-sim-container .pe-sim-kpi-card {
    background: white; border-radius: 12px; padding: 16px 12px;
    box-shadow: 0 2px 8px rgba(0,0,0,0.08); text-align: center;
    transition: transform 0.2s;
}
.pe-sim-container .pe-sim-kpi-card:hover { transform: translateY(-3px); }
.pe-sim-container .pe-sim-label {
    color: #718096; font-size: 0.75rem; text-transform: uppercase;
    letter-spacing: 0.5px; margin-bottom: 6px;
}
.pe-sim-container .pe-sim-value {
    font-size: 1.5rem; font-weight: 700; color: #2d3748;
}
.pe-sim-container .pe-sim-event-panel {
    background: linear-gradient(135deg, #fffbeb 0%, #fef3c7 100%);
    border-left: 4px solid #f59e0b; border-radius: 10px;
    padding: 16px 20px; margin-bottom: 24px;
}
.pe-sim-container .pe-sim-event-panel h4 { margin: 0 0 8px 0; color: #92400e; font-size: 0.9rem; }
.pe-sim-container .pe-sim-event-title { font-weight: 700; color: #78350f; margin-bottom: 4px; }
.pe-sim-container .pe-sim-event-desc { color: #92400e; font-size: 0.9rem; line-height: 1.5; }
.pe-sim-container .pe-sim-section-title {
    color: #2d3748; margin: 0 0 16px 0; font-size: 1.2rem;
}
.pe-sim-container .pe-sim-companies {
    display: grid; grid-template-columns: repeat(auto-fit, minmax(260px, 1fr));
    gap: 16px; margin-bottom: 28px;
}
.pe-sim-container .pe-sim-company-card {
    background: white; border-radius: 14px; overflow: hidden;
    box-shadow: 0 3px 12px rgba(0,0,0,0.08);
    transition: transform 0.2s, box-shadow 0.2s;
}
.pe-sim-container .pe-sim-company-card:hover {
    transform: translateY(-4px); box-shadow: 0 6px 20px rgba(0,0,0,0.12);
}
.pe-sim-container .pe-sim-company-header {
    padding: 14px 16px; color: white; display: flex;
    justify-content: space-between; align-items: center;
    font-size: 0.95rem;
}
.pe-sim-container .pe-sim-novamed-bg { background: linear-gradient(135deg, #3182ce, #2b6cb0); }
.pe-sim-container .pe-sim-fortaleza-bg { background: linear-gradient(135deg, #dd6b20, #c05621); }
.pe-sim-container .pe-sim-verdetech-bg { background: linear-gradient(135deg, #38a169, #2f855a); }
.pe-sim-container .pe-sim-retail-bg { background: linear-gradient(135deg, #e53e3e, #c53030); }
.pe-sim-container .pe-sim-sector-tag {
    background: rgba(255,255,255,0.25); padding: 2px 8px;
    border-radius: 10px; font-size: 0.7rem;
}
.pe-sim-container .pe-sim-company-body { padding: 14px 16px; }
.pe-sim-container .pe-sim-metric {
    display: flex; justify-content: space-between;
    padding: 4px 0; font-size: 0.88rem; color: #4a5568;
    border-bottom: 1px solid #f7fafc;
}
.pe-sim-container .pe-sim-metric span:last-child { font-weight: 600; color: #2d3748; }
.pe-sim-container .pe-sim-badge {
    display: inline-block; margin-top: 8px; padding: 3px 10px;
    border-radius: 12px; font-size: 0.75rem; font-weight: 600;
    background: #c6f6d5; color: #276749;
}
.pe-sim-container .pe-sim-badge-warning { background: #fed7d7; color: #9b2c2c; }
.pe-sim-container .pe-sim-badge-exited { background: #e2e8f0; color: #4a5568; }
.pe-sim-container .pe-sim-controls {
    background: white; border-radius: 16px; padding: 24px;
    box-shadow: 0 3px 12px rgba(0,0,0,0.08); margin-bottom: 28px;
}
.pe-sim-container .pe-sim-controls h3 { margin: 0 0 20px 0; color: #1a365d; }
.pe-sim-container .pe-sim-decision-block {
    margin-bottom: 20px; padding-bottom: 16px;
    border-bottom: 1px solid #edf2f7;
}
.pe-sim-container .pe-sim-decision-block h4 {
    color: #4a5568; font-size: 0.95rem; margin: 0 0 12px 0;
}
.pe-sim-container .pe-sim-attention-grid,
.pe-sim-container .pe-sim-select-grid {
    display: grid; grid-template-columns: repeat(auto-fit, minmax(150px, 1fr));
    gap: 12px;
}
.pe-sim-container .pe-sim-att-item label,
.pe-sim-container .pe-sim-sel-item label {
    display: block; font-size: 0.82rem; font-weight: 600;
    color: #4a5568; margin-bottom: 4px;
}
.pe-sim-container .pe-sim-att-total {
    text-align: center; margin-top: 10px; font-weight: 600;
    color: #4a5568; font-size: 0.9rem;
}
.pe-sim-container .pe-sim-att-total.pe-sim-over { color: #e53e3e; }
.pe-sim-container .pe-sim-mna-panel { font-size: 0.9rem; color: #4a5568; }
.pe-sim-container .pe-sim-mna-target {
    background: #f7fafc; border-radius: 8px; padding: 10px 14px;
    margin-bottom: 8px;
}
.pe-sim-container .pe-sim-mna-label { cursor: pointer; display: flex; align-items: flex-start; gap: 8px; }
.pe-sim-container .pe-sim-mna-label input { margin-top: 3px; }
.pe-sim-container .pe-sim-btn-row {
    display: flex; gap: 12px; align-items: center;
    margin-top: 20px; flex-wrap: wrap;
}
.pe-sim-container .pe-sim-history {
    background: white; border-radius: 16px; padding: 24px;
    box-shadow: 0 3px 12px rgba(0,0,0,0.08); margin-bottom: 28px;
    overflow-x: auto;
}
.pe-sim-container .pe-sim-history h3 { margin: 0 0 16px 0; color: #1a365d; }
.pe-sim-container .pe-sim-charts {
    display: grid; grid-template-columns: repeat(auto-fit, minmax(320px, 1fr));
    gap: 20px; margin-bottom: 30px;
}
.pe-sim-container .pe-sim-chart-box {
    background: white; border-radius: 16px; padding: 20px;
    box-shadow: 0 3px 12px rgba(0,0,0,0.08); min-height: 280px;
}
@media (max-width: 768px) {
    .pe-sim-container .pe-sim-fund-kpis { grid-template-columns: repeat(3, 1fr); }
    .pe-sim-container .pe-sim-companies { grid-template-columns: 1fr; }
    .pe-sim-container .pe-sim-attention-grid,
    .pe-sim-container .pe-sim-select-grid { grid-template-columns: repeat(2, 1fr); }
    .pe-sim-container .pe-sim-charts { grid-template-columns: 1fr; }
}


/* ===== v1.1.0 completion debrief (append-only) ===== */
.pe-cm { font-family: inherit; color: #1a365d; padding: 8px 4px; }
.pe-cm-scoreblock { text-align: center; margin-bottom: 18px; }
.pe-cm-scorenum { font-size: 3rem; font-weight: 800; line-height: 1; color: #1a365d; }
.pe-cm-scoremax { font-size: 1.2rem; font-weight: 600; color: #718096; }
.pe-cm-scorelabel { font-size: .9rem; text-transform: uppercase; letter-spacing: .05em; color: #718096; margin-top: 4px; }
.pe-cm-grade { font-size: 1.4rem; font-weight: 700; margin-top: 8px; color: #2c5282; }
.pe-cm-badge { display: inline-block; margin-top: 10px; padding: 5px 14px; border-radius: 999px; font-size: .85rem; font-weight: 700; }
.pe-cm-badge-pass { background: #c6f6d5; color: #22543d; }
.pe-cm-badge-miss { background: #fed7d7; color: #742a2a; }
.pe-cm-kpis { display: flex; flex-wrap: wrap; gap: 12px; justify-content: center; margin: 18px 0; }
.pe-cm-kpi { flex: 1 1 120px; max-width: 200px; background: #f7fafc; border: 1px solid #e2e8f0; border-radius: 10px; padding: 12px; text-align: center; }
.pe-cm-kpi-val { font-size: 1.5rem; font-weight: 800; color: #2c5282; }
.pe-cm-kpi-label { font-size: .8rem; color: #718096; margin-top: 4px; }
.pe-cm-insights { margin-top: 16px; background: #ebf8ff; border-left: 4px solid #3182ce; border-radius: 6px; padding: 12px 16px; }
.pe-cm-insights h6 { margin: 0 0 8px; font-weight: 700; color: #2c5282; }
.pe-cm-insights ul { margin: 0; padding-left: 18px; }
.pe-cm-insights li { margin-bottom: 6px; line-height: 1.4; }
.pe-cm-footer { margin-top: 16px; text-align: center; font-size: .85rem; color: #718096; }

