                    ]
                }
            };
        }

        _composite(fundMoic, fundIrr) {
            // v1.1.0: numeric 0-100 score ADDED (sim previously exposed only a categorical
            // verdict, so the gradebook read a missing score -> 0.0 for every learner).
            // Built from the fund headline metrics; MOIC weighted 60%, IRR 40%.
            // v1.1.1: saturation points moved onto the scale this model actually produces.
            // The book is marked at the blended exit multiple from round zero, so the fund
            // opens at 2.06x on 152M deployed and drifts up on uncosted debt paydown: the old
            // 3.0x / 24% caps sat BELOW an untouched default run, which printed 100/100.
            // Floor 2.0x = the inherited opening mark, so zero on this component means the
            // whole inherited value was handed back. Cap 5.0x = about 2.5 times that mark.
            // IRR floor and cap are the same two points expressed as the final-round IRR
            // the model reports for them: 41.4% and 123.6%, rounded to 40 and 125.
            var moicComp = Math.max(0, Math.min(1, (fundMoic - 2.0) / (5.0 - 2.0))) * 100;
            var irrComp = Math.max(0, Math.min(1, (fundIrr - 40.0) / (125.0 - 40.0))) * 100;
            return Math.round(moicComp * 0.6 + irrComp * 0.4);
        }

        getPerformanceSummary(history) {
            if (!history.length) return {};
            var t = function(k) { return window.mySimulation.t(k); };
            var last = history[history.length - 1];
            var fundMoic = last.results ? last.results.fundMoic || 0 : 0;
            var fundIrr = last.results ? last.results.fundIrr || 0 : 0;
            var totalDist = last.results ? last.results.cumulativeDistributions || 0 : 0;
            var composite = this._composite(fundMoic, fundIrr);

            var performanceId = 'below';
            var gradeKey = 'grade_below';
            var insights = [];

            // v1.1.1: bands are read off the composite so the number and the verdict cannot
            // disagree (EQIL 14.1). The old MOIC and IRR gates were on real-world PE benchmarks
            // that this model clears before the first decision, so every run graded Top Quartile.
            if (composite >= 80) {
                performanceId = 'top_quartile'; gradeKey = 'grade_top';
                insights.push(t('insight_top_1'));
                insights.push(t('insight_top_2'));
            } else if (composite >= 60) {
                performanceId = 'strong'; gradeKey = 'grade_strong';
                insights.push(t('insight_strong_1'));
                insights.push(t('insight_strong_2'));
            } else if (composite >= 35) {
                performanceId = 'adequate'; gradeKey = 'grade_adequate';
                insights.push(t('insight_adq_1'));
                insights.push(t('insight_adq_2'));
            } else {
                performanceId = 'below'; gradeKey = 'grade_below';
                insights.push(t('insight_below_1'));
                insights.push(t('insight_below_2'));
            }

            return {
                fundMoic: fundMoic,
                fundIrr: fundIrr,
                totalDistributions: totalDist,
                composite: composite,
                overallScore: composite,
                score: composite,
                performanceId: performanceId,
                performance: t(gradeKey),
                beatHurdle: fundIrr >= 8,
                insights: insights
            };
        }

        formatCompletionMessage(summary) {
            var t = function(k) { return window.mySimulation.t(k); };
            var s = summary || {};
            var score = (typeof s.composite === 'number') ? s.composite : 0;
            var grade = s.performance || '';
            var beat = !!s.beatHurdle;
            var moic = (s.fundMoic != null) ? s.fundMoic : 0;
            var irr = (s.fundIrr != null) ? s.fundIrr : 0;
            var dist = (s.totalDistributions != null) ? s.totalDistributions : 0;
            var insights = Array.isArray(s.insights) ? s.insights : [];

            var badgeClass = beat ? 'pe-cm-badge-pass' : 'pe-cm-badge-miss';
            var badgeText = beat ? t('cm_badge_beat') : t('cm_badge_missed');

            var kpi = function(label, val) {
                return '<div class="pe-cm-kpi"><div class="pe-cm-kpi-val">' + val + '</div><div class="pe-cm-kpi-label">' + label + '</div></div>';
            };

            var insightHtml = '';
            insights.forEach(function(it) { insightHtml += '<li>' + it + '</li>'; });

            return '' +
                '<div class="pe-cm">' +
                    '<div class="pe-cm-scoreblock">' +
                        '<div class="pe-cm-scorenum">' + score + '<span class="pe-cm-scoremax">/100</span></div>' +
                        '<div class="pe-cm-scorelabel">' + t('cm_score_label') + '</div>' +
                        '<div class="pe-cm-grade">' + grade + '</div>' +
                        '<span class="pe-cm-badge ' + badgeClass + '">' + badgeText + '</span>' +
                    '</div>' +
                    '<div class="pe-cm-kpis">' +
                        kpi(t('cm_moic_label'), moic.toFixed(2) + 'x') +
                        kpi(t('cm_irr_label'), irr.toFixed(1) + '%') +
                        kpi(t('cm_dist_label'), '$' + Math.round(dist) + 'M') +
                    '</div>' +
                    (insightHtml ? '<div class="pe-cm-insights"><h6>' + t('cm_insights_title') + '</h6><ul>' + insightHtml + '</ul></div>' : '') +
                    '<div class="pe-cm-footer">' + t('cm_footer') + '</div>' +
                '</div>';
        }

        getHint(state, results) {
            if (!results) return null;
            if (results.covenantBreaches && results.covenantBreaches !== 'None') {
                return window.mySimulation.t('hint_covenant');
            }
            if (results.fundMoic < 1.5 && state.currentPeriod >= 3) {
                return window.mySimulation.t('hint_low_moic');
            }
            if (state.domainState && state.domainState.ipoWindowOpen && state.currentPeriod === 2) {
                return window.mySimulation.t('hint_ipo_window');
            }
            if (state.domainState && state.domainState.remainingCapital < 10) {
                return window.mySimulation.t('hint_low_capital');
            }
            return null;
        }

